var t=`0214-fideua`;var s=`world-0214`;var a=`ES`;var n=`southern-europe`;var o=4;var r=25;var d={en:`Fideuà`,ua:`Фідеуа`};var l={en:`A traditional Spain dish made with shrimp, squid, garlic, tomato. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Іспанія. Основні інгредієнти: креветка, кальмар, часник, помідор. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`shrimp`,200,`g`],[`squid`,200,`g`],[`garlic`,3,`clove`],[`extra-virgin-olive-oil`,55,`ml`],[`tomato`,180,`g`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 13 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 13 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:13,i:[[`vermicelli-pasta`,350,`g`],[`fish-stock`,900,`ml`],[`saffron-threads`,.2,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:2,i:[[`lemon`,1,`pcs`],[`parsley`,15,`g`]]}];var h={slug:t,id:s,country:`ES`,region:n,servings:4,minutes:25,title:d,text:l,steps:u};export{a as country,h as default,s as id,r as minutes,n as region,o as servings,t as slug,u as steps,l as text,d as title};